// Generated by mgc from unfused_attn.mgc: do not edit, re-run mgc/mgcc.py.

#include <stdint.h>
#include "test.h"

#include "tile.h"
#include "fsync.h"
#include "mg_idma.h"
#include "mg_redmule.h"
#include "mg_event.h"

#define WAIT_MODE    WFE
#define QK_TIMESLOTS 2
#define PV_TIMESLOTS 8
#define SM_CHUNK                                                                                   \
    (SEQ_LENGTH / (MESH_X_TILES * MESH_Y_TILES) < 32 ? SEQ_LENGTH / (MESH_X_TILES * MESH_Y_TILES)  \
                                                     : 32)

/** L1 kernel (CORE): all pointers are L1 addresses. */
extern void l1_softmax_rows_fp16_spatz(uint32_t x, uint32_t p0, uint32_t p1);

/**
 * Unfused attention, O = softmax(Q @ Kt / sqrt(P)) @ V, as three back-to-back kernels over
 * the whole mesh, each through L2: attn = Q @ Kt and O = attn @ V output-static on RedMulE (as
 * mm_os_mgc), the row softmax of attn on Spatz in between.
 */
int main(void)
{
    /**
     * 0. Get the mesh-tile's hartid, mesh-tile coordinates and define its L1 base,
     * also initialize the controllers for the idma, redmule and fsync
     */
    uint32_t hartid = get_hartid();

    fsync_init();
    idma_init();
    redmule_init();

    eu_init();
    eu_redmule_init(0);
    eu_idma_init(0);
    eu_fsync_init(0);

    uint32_t y_id         = GET_Y_ID(hartid);
    uint32_t x_id         = GET_X_ID(hartid);
    uint32_t l1_tile_base = get_l1_base(hartid);

    uint32_t tile_h_max   = ((SEQ_LENGTH + MESH_Y_TILES - 1) / MESH_Y_TILES);
    uint32_t tile_w_max   = ((SEQ_LENGTH + MESH_X_TILES - 1) / MESH_X_TILES);
    uint32_t tile_w_p_max = ((PROJ_SIZE + MESH_X_TILES - 1) / MESH_X_TILES);
    int32_t tile_h;
    int32_t tile_w;
    int32_t tile_w_p;

    if (((tile_h_max * y_id) + tile_h_max) > SEQ_LENGTH) {
        tile_h = SEQ_LENGTH - (tile_h_max * y_id);
    } else {
        tile_h = tile_h_max;
    }

    if (((tile_w_max * x_id) + tile_w_max) > SEQ_LENGTH) {
        tile_w = SEQ_LENGTH - (tile_w_max * x_id);
    } else {
        tile_w = tile_w_max;
    }

    if (((tile_w_p_max * x_id) + tile_w_p_max) > PROJ_SIZE) {
        tile_w_p = PROJ_SIZE - (tile_w_p_max * x_id);
    } else {
        tile_w_p = tile_w_p_max;
    }

    if (tile_h < 1 || tile_w < 1 || tile_w_p < 1) {
        return 0;
    }
    uint16_t t_qk    = PROJ_SIZE / QK_TIMESLOTS;
    uint16_t t_pv    = SEQ_LENGTH / PV_TIMESLOTS;
    uint32_t sm_rows = SEQ_LENGTH / (MESH_X_TILES * MESH_Y_TILES);
    uint32_t sm_row0 = (y_id * MESH_X_TILES + x_id) * sm_rows;

    // each step's buffers are pinned to its loop: the three steps share L1
    // step 1: attn block (y_id, x_id), resident in L1, never initialized; Q and Kt slices
    // double buffered over the timeslots
    uint32_t len_a     = tile_w * 2;
    uint32_t std_a     = SEQ_LENGTH * 2;
    uint32_t reps_a    = (uint32_t)tile_h;
    uint32_t l1_addr_a = (l1_tile_base);
    uint32_t l2_addr_a =
        (uint32_t)attn_l2 + (tile_h_max * y_id * SEQ_LENGTH * 2) + (tile_w_max * x_id * 2);
    uint32_t len_xq       = t_qk * 2;
    uint32_t std_xq       = PROJ_SIZE * 2;
    uint32_t reps_xq      = (uint32_t)tile_h;
    uint32_t l1_addr_xq_0 = l1_addr_a + ((tile_h + 15) / 16 * 16 * tile_w * 2);
    uint32_t l1_addr_xq_1 = l1_addr_xq_0 + (tile_h * t_qk * 2);
    uint32_t l2_addr_xq   = (uint32_t)q_inp + (tile_h_max * y_id * PROJ_SIZE * 2);
    uint32_t len_wk       = tile_w * 2;
    uint32_t std_wk       = SEQ_LENGTH * 2;
    uint32_t reps_wk      = (uint32_t)t_qk;
    uint32_t l1_addr_wk_0 = l1_addr_xq_1 + (tile_h * t_qk * 2);
    uint32_t l1_addr_wk_1 = l1_addr_wk_0 + (t_qk * tile_w * 2);
    uint32_t l2_addr_wk   = (uint32_t)k_inp + (tile_w_max * x_id * 2);

    // step 2: chunks of SM_CHUNK full rows of attn
    uint32_t len_sm       = SM_CHUNK * SEQ_LENGTH * 2;
    uint32_t l1_addr_sm_0 = (l1_tile_base);
    uint32_t l1_addr_sm_1 = l1_addr_sm_0 + (SM_CHUNK * SEQ_LENGTH * 2);
    uint32_t l1_addr_sm_2 = l1_addr_sm_1 + (SM_CHUNK * SEQ_LENGTH * 2);
    uint32_t l2_addr_sm   = (uint32_t)attn_l2;

    // step 3: O block (y_id, x_id), resident in L1, never initialized; attn and V slices
    // double buffered over the timeslots
    uint32_t len_o     = tile_w_p * 2;
    uint32_t std_o     = PROJ_SIZE * 2;
    uint32_t reps_o    = (uint32_t)tile_h;
    uint32_t l1_addr_o = (l1_tile_base);
    uint32_t l2_addr_o =
        (uint32_t)o_out + (tile_h_max * y_id * PROJ_SIZE * 2) + (tile_w_p_max * x_id * 2);
    uint32_t len_xp       = t_pv * 2;
    uint32_t std_xp       = SEQ_LENGTH * 2;
    uint32_t reps_xp      = (uint32_t)tile_h;
    uint32_t l1_addr_xp_0 = l1_addr_o + ((tile_h + 15) / 16 * 16 * tile_w_p * 2);
    uint32_t l1_addr_xp_1 = l1_addr_xp_0 + (tile_h * t_pv * 2);
    uint32_t l2_addr_xp   = (uint32_t)attn_l2 + (tile_h_max * y_id * SEQ_LENGTH * 2);
    uint32_t len_wv       = tile_w_p * 2;
    uint32_t std_wv       = PROJ_SIZE * 2;
    uint32_t reps_wv      = (uint32_t)t_pv;
    uint32_t l1_addr_wv_0 = l1_addr_xp_1 + (tile_h * t_pv * 2);
    uint32_t l1_addr_wv_1 = l1_addr_wv_0 + (t_pv * tile_w_p * 2);
    uint32_t l2_addr_wv   = (uint32_t)v_inp + (tile_w_p_max * x_id * 2);

    volatile uint32_t xq_pt;
    volatile uint32_t wk_pt;
    volatile uint32_t sm_pt;
    volatile uint32_t xp_pt;
    volatile uint32_t wv_pt;
    volatile uint32_t xq_pt_next;
    volatile uint32_t wk_pt_next;
    volatile uint32_t sm_pt_next;
    volatile uint32_t xp_pt_next;
    volatile uint32_t wv_pt_next;

    mg_event_t idma_evt_a, idma_evt_xq, idma_evt_wk, idma_evt_o, idma_evt_xp, idma_evt_wv;
    mg_event_t ev_qk_0, ev_qk_1;
    mg_event_t *ev_qk_next, *ev_qk_curr;
    mg_event_t ev_pv_0, ev_pv_1;
    mg_event_t *ev_pv_next, *ev_pv_curr;
    mg_event_t idma_evts_sm_in_0, idma_evts_sm_in_1;
    mg_event_t *idma_evts_sm_in_next, *idma_evts_sm_in_curr;
    mg_event_t idma_evts_sm_out_0, idma_evts_sm_out_1;
    mg_event_t *idma_evts_sm_out_prev, *idma_evts_sm_out_curr;

    // start together, as the flat_attn_* tests do
    fsync_sync_global();
    eu_fsync_wait(WAIT_MODE);

    // 1. attn = Q @ Kt: the operands of timeslot i+1 are prefetched while RedMulE computes
    // timeslot i; the first job is a MATMUL, as attn is never loaded
    mg_idma_memcpy_2d(
        WAIT_MODE, 0, l2_addr_xq, l1_addr_xq_0, len_xq, std_xq, reps_xq, &idma_evt_xq, NULL);

    mg_idma_memcpy_2d(
        WAIT_MODE, 0, l2_addr_wk, l1_addr_wk_0, len_wk, std_wk, reps_wk, &idma_evt_wk, NULL);

    mg_redmule_matmul_enqueue(WAIT_MODE,
                              l1_addr_xq_0,
                              l1_addr_wk_0,
                              l1_addr_a,
                              (uint16_t)tile_h,
                              (uint16_t)t_qk,
                              (uint16_t)tile_w,
                              &ev_qk_0,
                              NULL);
    mg_idma_wait(0, WAIT_MODE, &idma_evt_xq);
    mg_idma_wait(0, WAIT_MODE, &idma_evt_wk);
    mg_redmule_gemm_commit_start();

    /**
     * pipeline: 2 stages; step i runs stage k on iteration i + 1 - k
     * xq     stages 0..1  depth 2
     * wk     stages 0..1  depth 2
     * ev_qk  stages 0..1  depth 2
     */
    for (int i = 0; i < QK_TIMESLOTS; i++) {
        if (i % 2) {
            xq_pt      = l1_addr_xq_1;
            xq_pt_next = l1_addr_xq_0;
            wk_pt      = l1_addr_wk_1;
            wk_pt_next = l1_addr_wk_0;
            ev_qk_curr = &ev_qk_1;
            ev_qk_next = &ev_qk_0;
        } else {
            xq_pt      = l1_addr_xq_0;
            xq_pt_next = l1_addr_xq_1;
            wk_pt      = l1_addr_wk_0;
            wk_pt_next = l1_addr_wk_1;
            ev_qk_curr = &ev_qk_0;
            ev_qk_next = &ev_qk_1;
        }

        if (i < (QK_TIMESLOTS - 1)) {
            mg_idma_memcpy_2d(WAIT_MODE,
                              0,
                              l2_addr_xq + ((i + 1) * t_qk * 2),
                              xq_pt_next,
                              len_xq,
                              std_xq,
                              reps_xq,
                              &idma_evt_xq,
                              NULL);

            mg_idma_memcpy_2d(WAIT_MODE,
                              0,
                              l2_addr_wk + ((i + 1) * t_qk * SEQ_LENGTH * 2),
                              wk_pt_next,
                              len_wk,
                              std_wk,
                              reps_wk,
                              &idma_evt_wk,
                              NULL);

            mg_redmule_gemm_enqueue(WAIT_MODE,
                                    xq_pt_next,
                                    wk_pt_next,
                                    l1_addr_a,
                                    (uint16_t)tile_h,
                                    (uint16_t)t_qk,
                                    (uint16_t)tile_w,
                                    ev_qk_next,
                                    NULL);
            mg_idma_wait(0, WAIT_MODE, &idma_evt_xq);
            mg_idma_wait(0, WAIT_MODE, &idma_evt_wk);
            mg_redmule_gemm_commit_start();
            mg_redmule_wait(WAIT_MODE, ev_qk_curr);
        } else {
            mg_redmule_wait(WAIT_MODE, ev_qk_curr);
        }
    }

    mg_idma_memcpy_2d(WAIT_MODE, 1, l2_addr_a, l1_addr_a, len_a, std_a, reps_a, &idma_evt_a, NULL);
    mg_idma_wait(1, WAIT_MODE, &idma_evt_a);
    fsync_sync_global();
    eu_fsync_wait(WAIT_MODE);

    // 2. attn = softmax(attn / sqrt(P)) by rows, in place in L2: this tile owns sm_rows full
    // rows and streams them through L1, chunk c + 1 loading and chunk c - 1 storing while Spatz
    // works on chunk c
    uint32_t r0 = sm_row0;

    mg_idma_memcpy_1d(WAIT_MODE,
                      0,
                      l2_addr_sm + (r0 * SEQ_LENGTH * 2),
                      l1_addr_sm_0,
                      len_sm,
                      &idma_evts_sm_in_0,
                      NULL);

    /**
     * pipeline: 3 stages; step c runs stage k on iteration c + 1 - k
     * sm                stages 0..2  depth 3
     * idma_evts_sm_in   stages 0..1  depth 2
     * idma_evts_sm_out  stages 1..2  depth 2
     */
    for (int c = 0; c < sm_rows / SM_CHUNK + 1; c++) {
        if (c % 2) {
            idma_evts_sm_in_curr  = &idma_evts_sm_in_1;
            idma_evts_sm_in_next  = &idma_evts_sm_in_0;
            idma_evts_sm_out_curr = &idma_evts_sm_out_1;
            idma_evts_sm_out_prev = &idma_evts_sm_out_0;
        } else {
            idma_evts_sm_in_curr  = &idma_evts_sm_in_0;
            idma_evts_sm_in_next  = &idma_evts_sm_in_1;
            idma_evts_sm_out_curr = &idma_evts_sm_out_0;
            idma_evts_sm_out_prev = &idma_evts_sm_out_1;
        }

        switch (c % 3) {
        case 0:
            sm_pt      = l1_addr_sm_0;
            sm_pt_next = l1_addr_sm_1;
            break;
        case 1:
            sm_pt      = l1_addr_sm_1;
            sm_pt_next = l1_addr_sm_2;
            break;
        case 2:
            sm_pt      = l1_addr_sm_2;
            sm_pt_next = l1_addr_sm_0;
            break;
        }

        if (c < (sm_rows / SM_CHUNK - 1)) {
            uint32_t r0 = sm_row0 + (c + 1) * SM_CHUNK;

            mg_idma_memcpy_1d(WAIT_MODE,
                              0,
                              l2_addr_sm + (r0 * SEQ_LENGTH * 2),
                              sm_pt_next,
                              len_sm,
                              idma_evts_sm_in_next,
                              NULL);
        }

        if (c < (sm_rows / SM_CHUNK)) {
            uint32_t r1 = sm_row0 + c * SM_CHUNK;
            mg_idma_wait(0, WAIT_MODE, idma_evts_sm_in_curr);

            l1_softmax_rows_fp16_spatz(sm_pt, SM_CHUNK, SEQ_LENGTH);

            mg_idma_memcpy_1d(WAIT_MODE,
                              1,
                              l2_addr_sm + (r1 * SEQ_LENGTH * 2),
                              sm_pt,
                              len_sm,
                              idma_evts_sm_out_curr,
                              NULL);
        }

        if (c > 0) {
            mg_idma_wait(1, WAIT_MODE, idma_evts_sm_out_prev);
        }
    }
    int c_last = sm_rows / SM_CHUNK - 1;
    fsync_sync_global();
    eu_fsync_wait(WAIT_MODE);

    // 3. O = attn @ V, as step 1
    mg_idma_memcpy_2d(
        WAIT_MODE, 0, l2_addr_xp, l1_addr_xp_0, len_xp, std_xp, reps_xp, &idma_evt_xp, NULL);

    mg_idma_memcpy_2d(
        WAIT_MODE, 0, l2_addr_wv, l1_addr_wv_0, len_wv, std_wv, reps_wv, &idma_evt_wv, NULL);

    mg_redmule_matmul_enqueue(WAIT_MODE,
                              l1_addr_xp_0,
                              l1_addr_wv_0,
                              l1_addr_o,
                              (uint16_t)tile_h,
                              (uint16_t)t_pv,
                              (uint16_t)tile_w_p,
                              &ev_pv_0,
                              NULL);
    mg_idma_wait(0, WAIT_MODE, &idma_evt_xp);
    mg_idma_wait(0, WAIT_MODE, &idma_evt_wv);
    mg_redmule_gemm_commit_start();

    /**
     * pipeline: 2 stages; step i runs stage k on iteration i + 1 - k
     * xp     stages 0..1  depth 2
     * wv     stages 0..1  depth 2
     * ev_pv  stages 0..1  depth 2
     */
    for (int i = 0; i < PV_TIMESLOTS; i++) {
        if (i % 2) {
            xp_pt      = l1_addr_xp_1;
            xp_pt_next = l1_addr_xp_0;
            wv_pt      = l1_addr_wv_1;
            wv_pt_next = l1_addr_wv_0;
            ev_pv_curr = &ev_pv_1;
            ev_pv_next = &ev_pv_0;
        } else {
            xp_pt      = l1_addr_xp_0;
            xp_pt_next = l1_addr_xp_1;
            wv_pt      = l1_addr_wv_0;
            wv_pt_next = l1_addr_wv_1;
            ev_pv_curr = &ev_pv_0;
            ev_pv_next = &ev_pv_1;
        }

        if (i < (PV_TIMESLOTS - 1)) {
            mg_idma_memcpy_2d(WAIT_MODE,
                              0,
                              l2_addr_xp + ((i + 1) * t_pv * 2),
                              xp_pt_next,
                              len_xp,
                              std_xp,
                              reps_xp,
                              &idma_evt_xp,
                              NULL);

            mg_idma_memcpy_2d(WAIT_MODE,
                              0,
                              l2_addr_wv + ((i + 1) * t_pv * PROJ_SIZE * 2),
                              wv_pt_next,
                              len_wv,
                              std_wv,
                              reps_wv,
                              &idma_evt_wv,
                              NULL);

            mg_redmule_gemm_enqueue(WAIT_MODE,
                                    xp_pt_next,
                                    wv_pt_next,
                                    l1_addr_o,
                                    (uint16_t)tile_h,
                                    (uint16_t)t_pv,
                                    (uint16_t)tile_w_p,
                                    ev_pv_next,
                                    NULL);
            mg_idma_wait(0, WAIT_MODE, &idma_evt_xp);
            mg_idma_wait(0, WAIT_MODE, &idma_evt_wv);
            mg_redmule_gemm_commit_start();
            mg_redmule_wait(WAIT_MODE, ev_pv_curr);
        } else {
            mg_redmule_wait(WAIT_MODE, ev_pv_curr);
        }
    }

    mg_idma_memcpy_2d(WAIT_MODE, 1, l2_addr_o, l1_addr_o, len_o, std_o, reps_o, &idma_evt_o, NULL);
    mg_idma_wait(1, WAIT_MODE, &idma_evt_o);

    // check the whole output on tile (0, 0), once every tile has written its block
    fsync_sync_global();
    eu_fsync_wait(WAIT_MODE);
    uint32_t errors = 0;

    if (y_id == 0) {
        if (x_id == 0) {
            uint16_t computed, expected, diff = 0;
            for (int i = 0; i < SEQ_LENGTH; i++) {
                for (int j = 0; j < PROJ_SIZE; j++) {
                    computed = *(volatile uint16_t *)(o_out + (i * PROJ_SIZE + j));
                    expected = *(volatile uint16_t *)(o_gold + (i * PROJ_SIZE + j));
                    diff = (computed > expected) ? (computed - expected) : (expected - computed);
                    if (diff > 0x0011) {
#if EVAL == 1
                        printf("Error detected at coordinates[%d][%d]: o_=%x o_gold=%x\n",
                               i,
                               j,
                               *(volatile uint16_t *)(o_out + (i * PROJ_SIZE + j)),
                               *(volatile uint16_t *)(o_gold + (i * PROJ_SIZE + j)));
#endif
                        errors++;
                    }
                }
            }
            printf("TILE %d: Number of errors: %d\n", hartid, errors);
        }
    }

    return errors;
}
